using System;using WildsEngine.Discoveries.Abstractions.Truths;using WildsEngine.Discoveries.Base;
namespace WildsEngine.Discoveries.Truths { public sealed class DiscoveryTruthProfile:IdentifierBase,IDiscoveryTruthProfile { public DiscoveryTruthProfile(Guid id,string slug,string version,string scope,ITruthCongealmentPolicy policy):base(id,slug){if(string.IsNullOrWhiteSpace(version)||string.IsNullOrWhiteSpace(scope))throw new ArgumentException("Version and scope required.");Version=version.Trim();Scope=scope.Trim();CongealmentPolicy=policy??throw new ArgumentNullException(nameof(policy));}public string Version{get;}public string Scope{get;}public ITruthCongealmentPolicy CongealmentPolicy{get;} } }
